def test_item_links(self) -> None: """ Tests item link creation by creating a multiworld of 2 worlds for every game and linking their items together. """ def setup_link_multiworld(world: Type[World], link_replace: bool) -> None: multiworld = MultiWorld(2) multiworld.game = {1: world.game, 2: world.game} multiworld.player_name = {1: "Linker 1", 2: "Linker 2"} multiworld.set_seed() item_link_group = [{ "name": "ItemLinkTest", "item_pool": ["Everything"], "link_replacement": link_replace, "replacement_item": None, }] args = Namespace() for name, option in world.options_dataclass.type_hints.items(): setattr(args, name, {1: option.from_any(option.default), 2: option.from_any(option.default)}) setattr(args, "item_links", {1: ItemLinks.from_any(item_link_group), 2: ItemLinks.from_any(item_link_group)}) multiworld.set_options(args) multiworld.set_item_links() # groups get added to state during its constructor so this has to be after item links are set multiworld.state = CollectionState(multiworld) gen_steps = ("generate_early", "create_regions", "create_items", "set_rules", "connect_entrances", "generate_basic") for step in gen_steps: call_all(multiworld, step) # link the items together and attempt to fill multiworld.link_items() multiworld._all_state = None call_all(multiworld, "pre_fill") distribute_items_restrictive(multiworld) call_all(multiworld, "post_fill") call_all(multiworld, "finalize_multiworld") self.assertTrue(multiworld.can_beat_game(CollectionState(multiworld)), f"seed = {multiworld.seed}")
for game_name, world_type in AutoWorldRegister.testable_worlds.items(): with self.subTest("Can generate with link replacement", game=game_name): > setup_link_multiworld(world_type, True)
